void sms_extract_number_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_sms_extract_number_obj_t * p_screen_param;
    lv_obj_t *      list = get_sms_extract_number_list_obj(ui_Screen);

    ;
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;

    p_screen_param      = (ui_screen_sms_extract_number_obj_t *) lv_obj_get_user_data(ui_Screen);

    //__inf("sms_menu_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    switch (key)
    {
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,0);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(get_focus_obj,0);
                app_fp_play_tts_menu(lv_label_get_text(label));
                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_ENTER:
            {
                lv_obj_t *      label_entry;

                get_focus_obj       = lv_obj_get_child(list,child_id);
                label_entry         = lv_obj_get_child(get_focus_obj,0);
                alv_am_win_enter(NULL,"extract_num_edit",lv_label_get_text(label_entry));
                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}




char * get_context_num_str(char * p_context,char * *end_str_pos)
{
    uint32_t        i,start_pos,end_pos;
    char *          p_str;

    if (p_context == NULL)
        return NULL;

    i                   = 0;

    while (p_context[i]) {
        if ((p_context[i] >= '0') && (p_context[i] <= '9')) {
            start_pos           = i;
            end_pos             = start_pos + 1;

            while ((p_context[end_pos] >= '0') && (p_context[end_pos] <= '9')) {
                end_pos++;
                }

            p_str               = lv_mem_alloc(end_pos - start_pos + 1);
            memcpy(&p_str[0],&p_context[start_pos],end_pos - start_pos);
            p_str[end_pos - start_pos] = 0;

            if (end_str_pos)
                *end_str_pos = &p_context[end_pos];

            return p_str;
            }

        i++;
        }

    if (end_str_pos)
        *end_str_pos = &p_context[i];

    return NULL;
}


static uint32_t is_have_context_num_str(char * p_context)
{
    uint32_t        i;

    if (p_context == NULL)
        return 0;

    i                   = 0;

    while (p_context[i]) {
        if ((p_context[i] >= '0') && (p_context[i] <= '9')) {
            return 1;
            }

        i++;
        }

    return 0;
}


