void ui_screen_sms_extract_number_enter(lv_obj_t * ui_cur_screen,sms_extract_number_ui_enter_param_t * enter_param)
{
    uint32_t        flag;

    flag                = 0;

    if (enter_param) {
        if (is_have_context_num_str(enter_param->p_context))
            flag = 1;

        if (is_have_context_num_str(enter_param->number))
            flag = 1;
        }

    if (flag)
        alv_am_win_enter(NULL,"extract_num",enter_param);
    else 
        sms_extarct_number_remind_screen(ui_cur_screen);
}


